package Servlet;
import Controlador.ProductosDAO;import Modelo.ItemCarrito;import Modelo.Productos;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet(name="CarritoAjaxController",urlPatterns={"/CarritoAjaxController"}) public class CarritoAjaxController extends HttpServlet{
 private final ProductosDAO dao=new ProductosDAO();
 @SuppressWarnings("unchecked") protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{resp.setContentType("application/json;charset=UTF-8");try{int id=Integer.parseInt(req.getParameter("idProducto"));String accion=req.getParameter("accion");HttpSession s=req.getSession();List<ItemCarrito> c=(List<ItemCarrito>)s.getAttribute("carrito");if(c==null)c=new ArrayList<>();if("agregar".equalsIgnoreCase(accion)){int n=Math.max(1,Integer.parseInt(req.getParameter("cantidad")));Productos p=dao.consultarProductosPorId(id);if(p==null||!p.isEstado()||!dao.reservarStock(id,n)){resp.setStatus(409);resp.getWriter().write("{\"error\":\"Stock insuficiente.\"}");return;}ItemCarrito item=null;for(ItemCarrito x:c)if(x.getIdProducto()==id)item=x;if(item==null){item=new ItemCarrito();item.setIdProducto(id);item.setDescripcion(p.getDescripcion());item.setPrecioUnitario(p.getPrecio());item.setCantidad(n);c.add(item);}else item.setCantidad(item.getCantidad()+n);}else if("eliminar".equalsIgnoreCase(accion)){Iterator<ItemCarrito> it=c.iterator();while(it.hasNext()){ItemCarrito x=it.next();if(x.getIdProducto()==id){dao.devolverStock(id,x.getCantidad());it.remove();break;}}}s.setAttribute("carrito",c);int total=0;for(ItemCarrito x:c)total+=x.getCantidad();int cantidadEsteProducto=0;for(ItemCarrito x:c)if(x.getIdProducto()==id)cantidadEsteProducto=x.getCantidad();resp.getWriter().write("{\"totalItems\":"+total+",\"cantidadProducto\":"+cantidadEsteProducto+",\"idProducto\":"+id+"}");}catch(Exception e){resp.setStatus(400);resp.getWriter().write("{\"error\":\"Solicitud no válida.\"}");}}
}
